var EDICAO_ID = 0;
$(document).ready(function() {
    //buscando ultima data de um diario válido
    ultima_data();
    ultimos_diarios();
    $('.dropdown #abre-los-subs').on('click', function() {
        $(this).parent().addClass('ativo');
    });
    $(document).on('click', function(e) {
        if ($(e.target).attr('id') !== 'abre-los-subs') {
            $('.dropdown #abre-los-subs').parent().removeClass('ativo');
        }
    });
    $(".data").datepicker({
        dateFormat: 'dd/mm/yy',
        dayNames: ['Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'],
        dayNamesMin: ['D', 'S', 'T', 'Q', 'Q', 'S', 'S', 'D'],
        dayNamesShort: ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb', 'Dom'],
        monthNames: ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'],
        monthNamesShort: ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun', 'Jul', 'Ago', 'Set', 'Out', 'Nov', 'Dez'],
        nextText: 'Próximo',
        prevText: 'Anterior',
        autoclose: true,
    });
    $("#outros-diarios").unbind('change').bind('change', function() {
        document.location = BASE_URL + $(this).val();
    });
    $("#tipoedicao").unbind('change').bind('change', function() {
        EDICAO_ID = $(this).val();
        carregarImagem(EDICAO_ID);
        mudarLabelEdicao(EDICAO_ID);
    });
    $("#buscarportipodata").unbind('click').bind('click', function() {
        EDICAO_ID = $('#tipoedicao').val();
        carregarImagem(EDICAO_ID);
        return false;
    });
    $('.busca_data .btn').on('click', function() {
        var i = $('.busca_data');
        if (i.find('#dataEdicaoPortal').val().length == 0) {
            i.find('span').remove();
            i.find('label').after('<span style="color: #900; font-size: 12px; padding: 0px 6px; margin-left: 20px; background: #ffc">É necessário informar uma data.</span>');
            return false;
        }
        var uri = i.attr('action').split('#')[0];
        var data = i.find('#dataEdicaoPortal').val().split('/');
        i.attr('action', uri + '#/p=1&di=' + data[2] + data[1] + data[0] + '&df=' + data[2] + data[1] + data[0]);
        // i.submit();
    });
    $('.busca_palavra .btn').on('click', function() {
        var i = $('.busca_palavra');
        var datai = '';
        var dataf = '';
        if (i.find('.q').val().length == 0) {
            i.find('span').remove();
            i.find('input:eq(2)').after('<span style="color: #900; font-size: 12px; padding: 0px 6px; margin-left: 20px; background: #ffc">É necessária uma palavra chave para a busca.</span>');
            return false;
        }
        if ($('#dataBuscaInicial').val().length > 0) {
            var datat = $('#dataBuscaInicial').val().split('/');
            datai = '&di=' + datat[2] + datat[1] + datat[0];
        }
        if ($('#dataBuscaFinal').val().length > 0) {
            var datat = $('#dataBuscaFinal').val().split('/');
            dataf = '&df=' + datat[2] + datat[1] + datat[0];
        }
        var uri = i.attr('action').split('#')[0];
        var data = i.find('.q').val();

        data = data.replace(/\"/g, '');

        var comp = '';
        if (i.find('input:radio[name=psq]:checked').length == 0 ||
            i.find('input:radio[name=psq]:checked').val() == "completa") {
            comp = '%22';
        }

        tema = '';
        if (i[0].hasAttribute("tema")) {
            tema = '/' + i.attr('tema');
        }
        i.attr('action',uri+'#'+tema+'/p=1&q='+comp+data+comp+datai+dataf);
        i.submit();
    });
    $('.busca-topo button').on('click', function() {
        var i = $('.busca-topo');
        var uri = i.attr('action').split('#')[0];
        var data = i.find('[name=q]').val();
        i.attr('action', uri + '#/p=1&q=' + data);
        i.submit();
    });
    $('#dataEdicaoPortal').unbind('change').bind('change', function() {
        var datat = $(this).val().split('/');
        dataf = datat[2] + '-' + datat[1] + '-' + datat[0];
        from_data(dataf);
    });

    $('#btn-autenticidade').click(function() {
        var hash = $('#hash').val();
        if (hash != '') {
            $.ajax({
                'url': BASE_URL + '/portal/edicoes/consulta_autenticidade/' + hash + '.json',
                success: function(data) {
                    $('#autenticidade-texto').html(data.msg);
                    if (data.error != true) {
                      $('#autenticidade-header').html('Código Válido');
                      $('a#download-box').attr('href', BASE_URL + ((SUBTEMA) ? '/' + SUBTEMA : '') + '/portal/edicoes/download/' + data.Edicao.id).show();
                    } else {
                      $('a#download-box').attr('href', '').hide();
                      $('#autenticidade-header').html('Código Inválido');
                    }
                    $('#modal-autenticidade').modal();
                }
            });
        }
    });
});

function validaHash(form) {
    if ($(form).attr('action').indexOf('#') == -1) {
        $(form).find('.btn').click();
        return false;
    }
}

function ultima_data() {
    $.ajax({
        url: BASE_URL + '/apifront/portal/edicoes/edicoes_from_data.json',
        data: {
            subtheme: SUBTEMA
        }
    }).done(function(data) {
        var obj = data;
        if (obj.erro) {
            alert(obj.msg);
            return;
        }
        if (obj.itens && obj.itens[0]) {
            $("#dataEdicaoPortal").val(obj.itens[0].data);
            EDICAO_ID = obj.itens[0].id;
            carregarImagem(EDICAO_ID);
            definirUrlDiarios(EDICAO_ID);
            populaAbas(obj.itens);
            $('#numero-edicao').html(formatar(obj.itens[0].numero))
        }
    });
}

function ultimos_diarios() {
    $.ajax({
        url: BASE_URL + '/apifront/portal/edicoes/ultimas_edicoes.json',
        data: {
            subtheme: SUBTEMA
        }
    }).done(function(data) {
        var obj = data;
        if (obj.erro) {
            return;
        }
        var levls = {};
        if (obj.itens.length > 0) {
            for (var t in obj.itens) {
                if (!levls[obj.itens[t].data]) {
                    levls[obj.itens[t].data] = [];
                }
                var curr = {
                    'nome': obj.itens[t].tipo_edicao_nome,
                    'id': obj.itens[t].id,
                    'numero': obj.itens[t].numero
                };
                if (obj.itens[t].suplemento == 1) {
                    curr.nome = curr.nome + ' SUPLEMENTO';
                }
                levls[obj.itens[t].data].push(curr);
            }
        }
        var op = '';
        for (var t in levls) {
            if (op != '') op += '</optgroup>';
            op += '<optgroup label="' + t + '">';
            for (var g in levls[t]) {
                op += '<option value="' + levls[t][g].id + '" >' + formatar(levls[t][g].numero) + ' - ' + levls[t][g].nome + '</option>';
            }
        }
        $("#tipoedicao").html(op);
    });
}

function carregarImagem(edicao_id) {
    definirUrlDiarios(edicao_id);
    if (edicao_id > 0) {
        var url = (CDN_URL != '' ? CDN_URL : BASE_URL) + ((SUBTEMA) ? '/' + SUBTEMA : '') + '/apifront/portal/edicoes/imagem_diario/' + edicao_id + '/1/imagem/1';
        var imagem = $('<div class="processing"></div>');
        $("#imagemCapa").parent().append(imagem);
        $("#imagemCapa").fadeOut('fast');
        var im = new Image();
        im.onload = function() {
            $("#imagemCapa").attr('src', url).fadeIn('fast');
            $("#imagemCapa").parent().find(".processing").fadeOut('slow', function() {
                $(this).remove();
            });
        }
        im.src = url;
    }
}

function definirUrlDiarios(edicao_id) {
    if (edicao_id > 0) {
        var urlPdf = BASE_URL + ((SUBTEMA) ? '/' + SUBTEMA : '') + '/ver-pdf/' + edicao_id + '/#e:' + edicao_id;
        var urlHTML = BASE_URL + ((SUBTEMA) ? '/' + SUBTEMA : '') + '/ver-html/' + edicao_id + '/#e:' + edicao_id;
        var urlJornal = BASE_URL + ((SUBTEMA) ? '/' + SUBTEMA : '') + '/ver-flip/' + edicao_id + '/#e:' + edicao_id;
        var urlFull = BASE_URL + ((SUBTEMA) ? '/' + SUBTEMA : '') + '/portal/edicoes/download/' + edicao_id;
        $("#downloadPdf").attr('href', urlPdf);
        $("#downloadHTML").attr('href', urlHTML);
        $("#downloadJornal").attr('href', urlJornal);
        $("#baixar-diario-completo").attr('href', urlFull);
    }
}

function limpaAbas() {
    $('#boxabas').slideUp('fast');
}

function populaAbas(obj) {
    if (obj.length > 1) {
        if (obj[1].suplemento) {
            $('#boxabas li:eq(0)').addClass('active').data('idDio', obj[0].id);
            $('#boxabas li:eq(1)').data('idDio', obj[1].id);
        } else {
            $('#boxabas li:eq(0)').addClass('active').data('idDio', obj[1].id);
            $('#boxabas li:eq(1)').data('idDio', obj[0].id);
        }
        $('#boxabas li.active').removeClass('active');
        $('#boxabas li:eq(0)').addClass('active');
        $('#boxabas a').unbind('click').bind('click', function(e) {
            e.preventDefault();
            $('#boxabas li.active').removeClass('active');
            $(this).parent().addClass('active');
            EDICAO_ID = $(this).parent().data('idDio');
            carregarImagem(EDICAO_ID);
            definirUrlDiarios(EDICAO_ID);
        });
        $('#boxabas').slideDown('fast');
    }
}

function formatar(n) {
    var x1 = n + '';
    var rgx = /(\d+)(\d{3})/;
    while (rgx.test(x1)) {
        x1 = x1.replace(rgx, '$1' + '.' + '$2');
    }
    return x1;
}

function from_data(data)
{
    let subtema = null;

    if (SUBTEMA != false) {
        subtema = {
            subtheme: SUBTEMA
        };
    }

    $.ajax({
        url: BASE_URL + ((SUBTEMA) ? '/' + SUBTEMA : '') + '/apifront/portal/edicoes/edicoes_from_data/' + data + '.json',
        data: subtema
    }).done(function(data) {
        var obj = data;
        if (obj.erro) {
            alert(obj.msg);
            return;
        }
        limpaAbas();
        var op = "";
        if (obj.itens.length > 0) {
            if (obj.itens && obj.itens[0]) {
                $("#dataEdicaoPortal").val(obj.itens[0].data);
                for (var t in obj.itens) {
                    op += '<option value="' + obj.itens[t].id + '" ' + ((EDICAO_ID == obj.itens[t].id) ? 'selected="selected"' : '') + '>' + obj.itens[t].tipo_edicao_nome + '</option>'
                }
                EDICAO_ID = obj.itens[0].id;
                carregarImagem(EDICAO_ID);
                definirUrlDiarios(EDICAO_ID);
                populaAbas(obj.itens);
                $('#numero-edicao').html(formatar(obj.itens[0].numero));
            }
            // $("#tipoedicao").html(op);
        }
    });
}

function changeFace() {
    var datat = $('#dataEdicaoPortal').val().split('/');
    dataf = datat[2] + '-' + datat[1] + '-' + datat[0];
    from_data(dataf);
    return false;
}

function mudarLabelEdicao(edicao_id) {
    $.ajax({
        url: BASE_URL + '/apifront/portal/edicoes/busca_edicao/' + edicao_id,
        data: {
            subtheme: SUBTEMA
        }
    }).done(function(data) {
        var obj = jQuery.parseJSON(data);
        if (obj.erro) {
            alert(obj.msg);
            return;
        }
        $('#numero-edicao').html(formatar(obj.Edicao.numero))
    });
}
